import{_ as e,o,c as a,ag as n}from"./chunks/framework.qXLDknWC.js";const f=JSON.parse('{"title":"Reasoning Effort","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/reasoning-effort.md","filePath":"configuration/reasoning-effort.md"}'),s={name:"configuration/reasoning-effort.md"};function r(l,t,i,d,g,h){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="reasoning-effort" tabindex="-1">Reasoning Effort <a class="header-anchor" href="#reasoning-effort" aria-label="Permalink to &quot;Reasoning Effort&quot;">​</a></h1><p>Reasoning effort controls <strong>how hard the model thinks</strong> before it writes a final answer. Character Vault sends this as part of the chat request when <strong>Enable reasoning</strong> is on (Settings → AI Config → Advanced Options).</p><p>This page explains what each level means, which models use which levels, and how Character Vault handles providers that only accept a subset of values.</p><h2 id="enable-reasoning-first" tabindex="-1">Enable reasoning first <a class="header-anchor" href="#enable-reasoning-first" aria-label="Permalink to &quot;Enable reasoning first&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Setting</th><th style="text-align:left;">What it does</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Enable reasoning</strong></td><td style="text-align:left;">Turns on thinking / chain-of-thought for models that support it. Off by default.</td></tr><tr><td style="text-align:left;"><strong>Show reasoning</strong></td><td style="text-align:left;">When on, the model’s thinking is shown in a collapsible section before the answer.</td></tr><tr><td style="text-align:left;"><strong>Reasoning Effort</strong></td><td style="text-align:left;">How much thinking budget to request (only shown when reasoning is enabled).</td></tr></tbody></table><p>Reasoning is useful for harder tasks: multi-step rewrites, consistency checks, complex character logic, or long instructions. It is usually slower and uses more tokens (and cost) than a normal reply.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you only need quick grammar or short polish, leave reasoning <strong>off</strong>. Turn it on when quality matters more than speed.</p></div><h2 id="what-the-levels-mean" tabindex="-1">What the levels mean <a class="header-anchor" href="#what-the-levels-mean" aria-label="Permalink to &quot;What the levels mean&quot;">​</a></h2><p>Character Vault offers six effort values. Higher effort generally means <strong>more thinking tokens</strong>, <strong>longer waits</strong>, and often <strong>better answers</strong> on hard problems. Exact behavior is decided by the model and the API gateway (NanoGPT, OpenRouter, OpenAI, etc.).</p><table tabindex="0"><thead><tr><th style="text-align:left;">Level</th><th style="text-align:left;">In short</th><th style="text-align:left;">Typical use</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Minimal</strong></td><td style="text-align:left;">Almost no thinking. Fastest.</td><td style="text-align:left;">Tiny edits, classification-style tasks, when you want speed.</td></tr><tr><td style="text-align:left;"><strong>Low</strong></td><td style="text-align:left;">Light thinking. Still quick.</td><td style="text-align:left;">Simple rewrites, short expansions.</td></tr><tr><td style="text-align:left;"><strong>Medium</strong></td><td style="text-align:left;">Balanced depth and speed. <strong>Default.</strong></td><td style="text-align:left;">General toolbar and chat work.</td></tr><tr><td style="text-align:left;"><strong>High</strong></td><td style="text-align:left;">Thorough thinking.</td><td style="text-align:left;">Complex edits, long context, careful reasoning.</td></tr><tr><td style="text-align:left;"><strong>Extra high (<code>xhigh</code>)</strong></td><td style="text-align:left;">Peak depth on <strong>OpenAI-style</strong> effort ladders.</td><td style="text-align:left;">Hardest tasks on GPT-5.x / o-series via OpenAI or OpenRouter.</td></tr><tr><td style="text-align:left;"><strong>Max</strong></td><td style="text-align:left;">Peak depth on <strong>many open / SOTA</strong> APIs.</td><td style="text-align:left;">Hardest tasks on DeepSeek V4, GLM-5.x, Kimi K3, and similar.</td></tr></tbody></table><h3 id="why-both-extra-high-and-max" tabindex="-1">Why both “Extra high” and “Max”? <a class="header-anchor" href="#why-both-extra-high-and-max" aria-label="Permalink to &quot;Why both “Extra high” and “Max”?&quot;">​</a></h3><p>Providers do not share one enum:</p><ul><li><strong>OpenAI-style</strong> APIs often use <code>minimal</code> → <code>low</code> → <code>medium</code> → <code>high</code> → <strong><code>xhigh</code></strong> (and sometimes <code>none</code>).</li><li><strong>DeepSeek V4</strong>, <strong>GLM-5 / 5.2</strong>, and several other SOTA stacks use a shorter ladder, often only <strong><code>high</code></strong> and <strong><code>max</code></strong> (plus turning thinking off).</li><li><strong>Kimi K2.5 / K2.6</strong> often only toggle thinking on or off; multi-level effort may be ignored or rejected. <strong>Kimi K3</strong> may only accept <strong><code>max</code></strong> today.</li></ul><p>Character Vault exposes both <strong>Extra high</strong> and <strong>Max</strong> so you can pick the name your model’s API expects. You do not need to memorize every provider.</p><h2 id="which-models-use-which-levels" tabindex="-1">Which models use which levels? <a class="header-anchor" href="#which-models-use-which-levels" aria-label="Permalink to &quot;Which models use which levels?&quot;">​</a></h2><p>This is a practical guide, not a guarantee. Gateways can remap or restrict values.</p><h3 id="gpt-and-oss-style-ladders" tabindex="-1">GPT and “OSS-style” ladders <a class="header-anchor" href="#gpt-and-oss-style-ladders" aria-label="Permalink to &quot;GPT and “OSS-style” ladders&quot;">​</a></h3><p>Models that follow an OpenAI-like effort scale (many <strong>GPT-5.x</strong>, <strong>o-series</strong>, and some <strong>open weights</strong> served with the same API shape) usually understand:</p><ul><li><strong>Minimal, Low, Medium, High</strong> for everyday control</li><li><strong>Extra high (<code>xhigh</code>)</strong> for maximum depth on that ladder</li></ul><p><strong>Medium</strong> is a safe default for these models.</p><h3 id="sota-thinking-first-models-deepseek-glm-kimi-etc" tabindex="-1">SOTA / thinking-first models (DeepSeek, GLM, Kimi, etc.) <a class="header-anchor" href="#sota-thinking-first-models-deepseek-glm-kimi-etc" aria-label="Permalink to &quot;SOTA / thinking-first models (DeepSeek, GLM, Kimi, etc.)&quot;">​</a></h3><p>Newer flagship thinking models often do <strong>not</strong> support the full low/medium ladder:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Family (examples)</th><th style="text-align:left;">Typical effort values</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>DeepSeek V4</strong> (thinking / <code>:thinking</code> variants)</td><td style="text-align:left;"><code>high</code>, <code>max</code> (and sometimes <code>none</code> to disable)</td><td style="text-align:left;">Official APIs often map <code>low</code>/<code>medium</code> → <code>high</code> and <code>xhigh</code> → <code>max</code>. Some gateways instead <strong>reject</strong> <code>medium</code> and list only <code>none</code>, <code>high</code>, <code>max</code>.</td></tr><tr><td style="text-align:left;"><strong>GLM-5 / GLM-5.2</strong></td><td style="text-align:left;"><code>high</code>, <code>max</code> (<code>max</code> is often the model default)</td><td style="text-align:left;">Use <strong>High</strong> for cost/latency, <strong>Max</strong> for hardest agentic or coding-style work.</td></tr><tr><td style="text-align:left;"><strong>Kimi K2.5 / K2.6</strong></td><td style="text-align:left;">Thinking on/off more than multi-level effort</td><td style="text-align:left;">Effort dropdown may have little effect; enable reasoning still matters for thinking output.</td></tr><tr><td style="text-align:left;"><strong>Kimi K3</strong></td><td style="text-align:left;">Often <strong><code>max</code> only</strong> today</td><td style="text-align:left;">Pick <strong>Max</strong> when using these IDs.</td></tr><tr><td style="text-align:left;"><strong>OpenRouter</strong> unified <code>reasoning.effort</code></td><td style="text-align:left;">Can include <code>none</code>, <code>minimal</code>, <code>low</code>, <code>medium</code>, <code>high</code>, <code>xhigh</code>, <code>max</code></td><td style="text-align:left;">Per-model support varies; OpenRouter may map your choice to what the upstream model allows.</td></tr></tbody></table><h3 id="quick-rule-of-thumb" tabindex="-1">Quick rule of thumb <a class="header-anchor" href="#quick-rule-of-thumb" aria-label="Permalink to &quot;Quick rule of thumb&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">You are using…</th><th style="text-align:left;">Prefer…</th></tr></thead><tbody><tr><td style="text-align:left;">GPT / o-series / OpenAI-style</td><td style="text-align:left;">Minimal → High, or <strong>Extra high</strong> for max depth</td></tr><tr><td style="text-align:left;">DeepSeek V4, GLM-5.x, many SOTA open models</td><td style="text-align:left;"><strong>High</strong> or <strong>Max</strong></td></tr><tr><td style="text-align:left;">Not sure</td><td style="text-align:left;">Start with <strong>Medium</strong> or <strong>High</strong>; if the request fails on effort, Character Vault remaps for you</td></tr></tbody></table><h2 id="automatic-remapping" tabindex="-1">Automatic remapping <a class="header-anchor" href="#automatic-remapping" aria-label="Permalink to &quot;Automatic remapping&quot;">​</a></h2><p>Character Vault always sends the effort you selected when reasoning is on. If the provider returns an error like “unsupported <code>reasoning_effort</code>” and lists allowed values, Character Vault:</p><ol><li>Picks the <strong>closest supported</strong> level (never maps down to “no thinking” while reasoning is enabled).</li><li>Treats <strong>Max</strong> and <strong>Extra high</strong> as <strong>peers</strong> when only one of them is allowed.</li><li><strong>Remembers</strong> rejections for that base URL + model for the rest of the session so the next request does not fail the same way.</li></ol><p>You may see a console message such as <code>remapped parameters: reasoning_effort=high</code>. That means your setting was adjusted for compatibility, not that reasoning was turned off.</p><p>If a parameter is completely unsupported (not just a bad value), Character Vault may <strong>drop</strong> it and retry. Non-standard sampler fields (<code>min_p</code>, <code>top_k</code>, <code>repetition_penalty</code>) can be dropped the same way on strict OpenAI-compatible hosts; that is separate from effort.</p><h2 id="practical-recommendations" tabindex="-1">Practical recommendations <a class="header-anchor" href="#practical-recommendations" aria-label="Permalink to &quot;Practical recommendations&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Goal</th><th style="text-align:left;">Suggestion</th></tr></thead><tbody><tr><td style="text-align:left;">Everyday character editing with a GPT-style model</td><td style="text-align:left;"><strong>Medium</strong></td></tr><tr><td style="text-align:left;">Faster toolbar passes</td><td style="text-align:left;"><strong>Low</strong> or <strong>Minimal</strong>, or turn reasoning <strong>off</strong></td></tr><tr><td style="text-align:left;">Hard lore / multi-field consistency</td><td style="text-align:left;"><strong>High</strong></td></tr><tr><td style="text-align:left;">DeepSeek / GLM hard reasoning</td><td style="text-align:left;"><strong>High</strong> first; <strong>Max</strong> if answers are shallow</td></tr><tr><td style="text-align:left;">OpenAI peak reasoning</td><td style="text-align:left;"><strong>Extra high</strong> when the model supports it</td></tr><tr><td style="text-align:left;">Cost / latency sensitive</td><td style="text-align:left;">Lower effort, or disable reasoning</td></tr></tbody></table><p>Higher effort does <strong>not</strong> always improve creative prose. For roleplay flavor and style, sampler settings (temperature, top-p, etc.) often matter more. Use high effort when the task is <strong>logical or multi-step</strong>, not only when you want “more words.”</p><h2 id="related-settings" tabindex="-1">Related settings <a class="header-anchor" href="#related-settings" aria-label="Permalink to &quot;Related settings&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/configuration/ai-setup">AI Setup</a> — base URL, API key, model, streaming, NanoGPT / Synthetic / OpenRouter usage cards</li><li><a href="/CharacterVault/docs/configuration/sampler-settings">Sampler Settings</a> — temperature, top-p, min-p, context length</li><li><a href="/CharacterVault/docs/features/editor">Editor &amp; AI Toolkit</a> — toolbar operations that use these settings</li><li><a href="/CharacterVault/docs/features/ai-assistant">AI Assistant Orion</a></li><li><a href="/CharacterVault/docs/features/ai-agent">AI Agent</a></li></ul><h2 id="finding-this-in-the-app" tabindex="-1">Finding this in the app <a class="header-anchor" href="#finding-this-in-the-app" aria-label="Permalink to &quot;Finding this in the app&quot;">​</a></h2><ol><li>Open a character workspace.</li><li><strong>Settings</strong> → <strong>AI Config</strong> → <strong>Advanced Options</strong>.</li><li>Turn on <strong>Enable reasoning</strong>.</li><li>Choose <strong>Reasoning Effort</strong>.</li><li>Click <strong>Save Settings</strong>.</li></ol>',37)])])}const m=e(s,[["render",r]]);export{f as __pageData,m as default};
